   ========================================================= */

/* ── 1. 改造折叠按钮 (极简透明底，无三角) ── */
.chat-detail-screen {
  --thinking-btn-bg: transparent;
  --thinking-btn-color: #8e8e8e; /* Ins 经典的次级灰色 */
  --thinking-btn-border: none;
  --thinking-btn-shadow: none;
  --thinking-btn-padding: 4px 0px; 
}

/* ── 2. 隐藏默认图标、小三角，修改按钮文字 ── */
.nuo-thinking-icon { display: none !important; }
.nuo-thinking-arrow { display: none !important; } /* 🎯 咔嚓掉小三角 */
.nuo-thinking-label { font-size: 0 !important; }
.nuo-thinking-label::after {
    content: "@하트 비트" !important;
    font-size: 12px !important;
    font-weight: 600 !important;
    color: #8e8e8e !important;
}

/* ── 3. 改造面板基础样式 (Ins 经典白底卡片) ── */
.chat-detail-screen {
  --thinking-panel-bg: #ffffff;
