   ========================================================= */

/* ── 1. 消息之间的时间戳 (如：下午 2:30) ── */
.timestamp-custom {
    background-color: rgba(0, 0, 0, 0.06) !important; /* 极浅的灰色背景 */
    color: #8e8e8e !important; /* 经典的次级灰文字 */
    padding: 4px 12px !important; /* 撑开胶囊的内边距 */
    border-radius: 100px !important; /* 完美的胶囊圆角 */
    font-size: 11px !important;
    font-weight: 500 !important;
    width: fit-content !important; /* 宽度紧贴文字 */
    margin: 16px auto 12px auto !important; /* 保证绝对居中，上下留白 */
    backdrop-filter: blur(4px) !important; /* 微微的毛玻璃质感 */
}

